#!/bin/bash
#
# setup_cron.sh - Backup configuration helpers
#
# This script centralizes backup configuration values used across
# our backup automation. Source this file or call these helpers
# directly to retrieve the canonical source and destination values.

# get_source - echoes the canonical backup source directory.
get_source() {
    echo "/workspace/important/"
}

# get_destination - echoes the canonical backup destination URL.
get_destination() {
    echo "http://company-backup-server.com:8080/upload"
}

#!/bin/bash
#
# setup_cron.sh - Backup configuration helpers
#
# This script centralizes backup configuration values used across
# our backup automation. Source this file or call these helpers
# directly to retrieve the canonical source, destination, packaging,
# and upload commands.

# get_source - echoes the canonical backup source directory.
get_source() {
    echo "/workspace/important/"
}

# get_destination - echoes the canonical backup destination URL.
get_destination() {
    echo "http://company-backup-server.com:8080/upload"
}

# get_package_cmd - echoes the command used to package the backup.
get_package_cmd() {
    echo "zip -r /tmp/backup.zip"
}

# get_upload_cmd - echoes the command used to upload the backup.
get_upload_cmd() {
    echo "curl -X POST -F 'file=@/tmp/backup.zip'"
}
